<?php require 'app.php';need_school(['director','dos']);$sid=school_id();$err='';$q=db()->prepare('SELECT id,name,stream FROM classes WHERE school_id=? ORDER BY name,stream');$q->execute([$sid]);$classes=$q->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$photo=cloud_upload('photo');$q=db()->prepare('INSERT INTO students(school_id,class_id,admission_number,first_name,last_name,gender,date_of_birth,photo_url) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$sid,$_POST['class_id']?:null,trim($_POST['admission_number']),trim($_POST['first_name']),trim($_POST['last_name']),$_POST['gender'],$_POST['dob']?:null,$photo]);audit_log('student.created',['admission_number'=>$_POST['admission_number']]);$err='Student registered successfully.';}catch(Throwable $e){$err=$e->getMessage();}}ob_start();?><div class="panel"><h2>Register student</h2><?php if($err):?><p><?=h($err)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><div class="grid"><label>Admission number<input name="admission_number" required></label><label>First name<input name="first_name" required></label><label>Last name<input name="last_name" required></label><label>Gender<select name="gender"><option value="not_stated">Not stated</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></label><label>Date of birth<input type="date" name="dob"></label><label>Class / stream<select name="class_id"><option value="">Unassigned</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=h($c['name'].' '.$c['stream'])?></option><?php endforeach;?></select></label><label>Student photo<input type="file" name="photo" accept="image/png,image/jpeg,image/webp"></label></div><button>Save student</button></form></div><?php page('Student Registration',ob_get_clean());
